from pathlib import Path
p=Path('work/viewer-pdf.html');s=p.read_text(encoding='utf-8')
s=s.replace('depEl(\'depSave\').onclick=depSaveEditor;',"depSimplifyEditor();depEl('depSave').onclick=depSaveEditor;")
s=s.replace("function depSaveEditor(){", "function depSaveEditor(){depSyncSimpleOfficer();")
s=s.replace("else depOpen(u.id);drag=null", "else depShowDutyCard(depUnits.find(v=>v.id===el.dataset.id)||u);drag=null")
s=s.replace("if(e.detail===0)depOpen(u.id)","if(e.detail===0)depShowDutyCard(depUnits.find(v=>v.id===el.dataset.id)||u)")
s=s.replace("el.textContent=({machan:'M',morcha:'MO',rider:'R',qrt:'Q',naka:'N',patrol:'P',officer:'★',barricade:'B',ambulance:'+'})[u.type]||'D';", "el.innerHTML=depMapIcon(u.type);el.style.background=({officer:'#195d9b',rider:'#087f7c',patrol:'#5c4c9b',qrt:'#5c4c9b',barricade:'#b46b12',naka:'#b46b12',machan:'#2d6575',morcha:'#65533a'})[u.type]||'#476971';")
needle="depPersist();depOpen(u.id)};depEl('depUndoPoint')"
assert needle in s
s=s.replace(needle,"depAnimate=true;depEl('depAnimate').checked=true;depPersist();depOpen(u.id);depEl('depLocate').click();depEl('depStatus').textContent='Route ready · rider / vehicle is moving';depToast('Path ready — movement started. Click the icon to edit.')} ;depEl('depUndoPoint')")
start=s.index('// Direct 3D duty-object picking')
addon=r'''// Simple deployment interface: primary actions first, full roster remains editable.
function depToast(text){let el=document.getElementById('depToast');if(!el){el=document.createElement('div');el.id='depToast';el.style.cssText='position:absolute;bottom:28px;left:50%;transform:translateX(-50%);z-index:24;padding:12px 18px;background:#173e45ed;color:white;border-radius:9px;font:13px Segoe UI;pointer-events:none';sceneEl.append(el)}el.textContent=text;el.hidden=false;clearTimeout(el.timer);el.timer=setTimeout(()=>el.hidden=true,6000)}
function depMapIcon(type){const paths={officer:'<circle cx="12" cy="6" r="3"/><path d="M6 12h12v6h-4v5h-4v-5H6z"/>',barricade:'<path d="M2 6h20v10H2zM5 16v6M19 16v6"/><path d="m5 7 6 8m3-8 6 8" stroke="#263c49" stroke-width="3"/>',naka:'<path d="M2 6h20v10H2zM5 16v6M19 16v6"/><path d="m5 7 6 8m3-8 6 8" stroke="#263c49" stroke-width="3"/>',rider:'<circle cx="5" cy="17" r="4" fill="none" stroke="white" stroke-width="2"/><circle cx="19" cy="17" r="4" fill="none" stroke="white" stroke-width="2"/><path d="m5 17 6-8 8 8h-8l-4-6h9" fill="none" stroke="white" stroke-width="2"/><circle cx="13" cy="4" r="2"/>',patrol:'<path d="m4 7 2-4h12l2 4 2 3v9H2v-9z"/><path d="M6 7h12" stroke="#31436a" stroke-width="3"/><path d="M5 18v4m14-4v4" stroke="white" stroke-width="3"/>',machan:'<path d="M3 7 12 1l9 6zM5 8h14v7H5zM7 15l-3 9m13-9 3 9M7 20h10" fill="none" stroke="white" stroke-width="2"/>',morcha:'<path d="M2 14h20v8H2zM5 9h14v5H5z"/><circle cx="12" cy="5" r="3"/>'};const body=paths[type==='qrt'?'patrol':type]||'<circle cx="12" cy="12" r="5"/>';return '<svg viewBox="0 0 24 24" width="16" height="16" fill="white" aria-hidden="true">'+body+'</svg>'}
function depSyncSimpleOfficer(){const name=depEl('depSimpleName');if(!name)return;const u=depUnits.find(v=>v.id===depSelected);if(!u)return;const lines=depEl('depPersonnel').value.split('\n'),old=(lines[0]||'').split('|').map(v=>v.trim());if(name.value.trim()||old[0]){old[0]=name.value.trim();old[1]=depEl('depSimpleRank').value.trim();lines[0]=old.join(' | ');depEl('depPersonnel').value=lines.join('\n')}}
function depSimplifyEditor(){const ed=depEl('depEditor'),u=depUnits.find(v=>v.id===depSelected);if(!u)return;const heading=ed.querySelector('h3'),name=depEl('depName').closest('label'),typeRow=depEl('depType').closest('.dep-grid'),position=depEl('depPlace').parentElement,actions=depEl('depSave').parentElement,route=depEl('depDrawRoute').closest('fieldset');const advanced=document.createElement('details');advanced.className='dep-advanced';advanced.innerHTML='<summary>Advanced details · strength, shifts, full staff, coordinates</summary>';for(const child of [...ed.children])advanced.append(child);ed.append(heading,name,typeRow);const hint=document.createElement('p');hint.className='dep-simple-hint';hint.textContent='1. Select duty  →  2. Place / drag  →  3. Draw path for rider / car';ed.prepend(hint);depEl('depLocate').textContent='View on map';depEl('depPlace').textContent=u.position?'Move on map':'Place on map';depEl('depUnplace').style.display='none';ed.append(position);const person=u.personnel?.[0]||{};const staff=document.createElement('div');staff.className='dep-grid';staff.innerHTML='<label>Officer name<input id="depSimpleName" placeholder="Assign officer name" value="'+depEsc(person.name||'')+'"></label><label>Rank<input id="depSimpleRank" placeholder="SI / ASI / Constable" value="'+depEsc(person.rank||'')+'"></label>';ed.append(staff);const routeExtra=document.createElement('details');routeExtra.innerHTML='<summary>Speed / route settings</summary>';const routeGrid=route.querySelector('.dep-grid');routeExtra.append(routeGrid);route.append(routeExtra);route.querySelector('legend').textContent='Rider / vehicle path';route.querySelector('.dep-muted').textContent='Click Draw path, choose road points, then Start movement.';depEl('depDrawRoute').textContent='Draw / change path';depEl('depClearRoute').textContent='Remove path';ed.append(route,actions,advanced);depEl('depSave').textContent='Save';depEl('depDelete').textContent='Delete';depEl('depDuplicate').style.display='none';advanced.append(depEl('depDuplicate'));}
const depSimpleStyle=document.createElement('style');depSimpleStyle.textContent='.dep-panel{width:340px}.dep-head b{font-family:Segoe UI;font-size:19px}.dep-simple-hint{padding:9px;background:#e5ece4;border-radius:7px;font-size:11px;line-height:1.6}.dep-advanced{margin-top:14px;border-top:1px solid #ccd3c4;padding-top:12px}.dep-advanced summary{cursor:pointer;font-size:11px;color:#64776e}.dep-icon{width:24px;height:24px;display:grid;place-items:center;margin:-12px 0 0 -12px;border:1.5px solid #fff4d8}.dep-icon[hidden]{display:none!important}.dep-list{max-height:170px}.dep-list button{padding:8px}.dep-panel fieldset{margin:10px 0;padding:9px;border:1px solid #ccd3c4;border-radius:8px}.dep-panel summary{padding:7px 0}.dep-panel #depSummary{font-size:11px}.dep-panel .dep-tools{padding:9px}.dep-quick{display:flex;flex-wrap:wrap;gap:5px;margin:10px 0}.dep-quick button{display:flex;align-items:center;gap:5px}.dep-quick svg{background:#315b66;border-radius:3px;padding:2px}';document.head.append(depSimpleStyle);
const depTools=depEl('depNew').parentElement,depBackup=document.createElement('details');depBackup.innerHTML='<summary>Backup / import / restore</summary><div class="dep-tools"></div>';for(const id of ['depExport','depCSV','depImportButton','depImport','depRestore'])depBackup.lastElementChild.append(depEl(id));depPanel.querySelector('.dep-scroll').append(depBackup);depEl('depNew').textContent='+ New duty';const depSimpleSummary=document.createElement('details');depSimpleSummary.innerHTML='<summary>Force totals / roster notes</summary>';const totals=depEl('depSummary');totals.before(depSimpleSummary);depSimpleSummary.append(totals);const note=depPanel.querySelector('.dep-scroll > .dep-muted');if(note)depSimpleSummary.append(note);const depQuick=document.createElement('div');depQuick.className='dep-quick';for(const type of ['officer','barricade','rider','patrol','qrt','machan','morcha']){const b=document.createElement('button');b.innerHTML=depMapIcon(type)+' '+DEP_TYPES[type];b.onclick=()=>{depNew(type);depEl('depEditor').scrollIntoView({block:'nearest'})};depQuick.append(b)}depEl('depSearch').after(depQuick);depCatalogue.hidden=true;depEl('depFinishRoute').textContent='Start movement';depPanel.querySelector('.dep-head div div').textContent='SELECT DUTY · PLACE ON MAP · DRAW PATH';
'''
s=s[:start]+addon+s[start:]
p.write_text(s,encoding='utf-8')
print('Simplified panel and added clear map icons; route finish starts movement')
